SET NAMES utf8mb4;
-- 004 : butin Wowlheim par categorie de creature x palier (voir docs/RESOURCES.md).
-- reference_loot_template : entrees 8300000+ (9300000+ impossible : mincountOrRef est un MEDIUMINT signe) ; creature_loot_template : UNE ligne de reference ajoutee par LootId eligible
-- (item = id de la reference, mincountOrRef = -id). Aucune ligne de butin existante n'est modifiee ; seule modification d'une ligne existante : LootId des critters cerfs/biches (ci-dessous).
-- gibier critter (cerfs, biches, faons ; Valheim : le cerf est le premier gibier) : LootId = Entry (aucun butin dans WoW).
UPDATE `creature_template` SET `LootId` = `Entry` WHERE `Entry` IN (620,883,890,2098,4166,10780,12296,12298,14869) AND `LootId` IN (0, `Entry`);
-- gibier ajoute aux zones de depart sans bete a bois/cornes (rules.GAME_SPAWNS) : critters existants, positions de critters existants.
DELETE FROM `creature` WHERE `guid` BETWEEN 9700001 AND 9700999;
DELETE FROM `reference_loot_template` WHERE `entry` BETWEEN 8300000 AND 8399999;
DELETE FROM `creature_loot_template` WHERE `item` BETWEEN 8300000 AND 8399999 AND `mincountOrRef` < 0;
